static void facDif(LinkedList<Integer>L,int n,int i){
    int p=prod(L);

    if(p>=n){
        if(p==n)System.out.println(L);
        return;
    }

    for(int k=i;k<=n;k++)
        if(n%(p*k)==0){
            L.add(k);
            facDif(L,n,k+1);
            L.removeLast();
        }
}
